/**
 * 幀步進按鈕插件（上一幀/下一幀）
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { prevIcon, nextIcon } from '../../renderer/icons';
import styles from './styles.css?inline';

export interface FrameStepPluginOptions extends ControlPluginOptions {
    position?: 'left' | 'right';
    order?: number;
    /** 長按初始延遲（毫秒） */
    initialDelay?: number;
    /** 長按初始重複間隔（毫秒） */
    repeatInterval?: number;
    /** 長按最快重複間隔（毫秒），加速後不會低於此值 */
    minInterval?: number;
    /** 加速因子，每次重複後間隔乘以此值（0.85 = 每次快 15%） */
    accelerationFactor?: number;
}

export const FrameStepPlugin: MpvPlugin<FrameStepPluginOptions> = {
    name: 'frameStep',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new FrameStepManager(player, {
            position: options.position ?? 'left',
            order: options.order ?? 10,
            initialDelay: options.initialDelay ?? 400,
            repeatInterval: options.repeatInterval ?? 100,
            minInterval: options.minInterval ?? 16,
            accelerationFactor: options.accelerationFactor ?? 0.85,
        });
    },
};

export class FrameStepManager extends ControlPlugin<Required<FrameStepPluginOptions>> {
    readonly name = 'frameStep';

    // DO NOT initialize these fields here! JavaScript field initializers run AFTER super(),
    // which would reset values set during createEl() back to null.
    private prevBtn!: HTMLButtonElement | null;
    private nextBtn!: HTMLButtonElement | null;

    protected createEl(): HTMLElement {
        // 創建一個包裝容器（用於管理兩個按鈕）
        const wrapper = document.createElement('div');
        wrapper.className = 'vp-frame-step-wrapper';
        wrapper.style.display = 'contents'; // 讓子元素直接作為 flex 項目

        // 上一幀按鈕
        this.prevBtn = document.createElement('button');
        this.prevBtn.className = 'vp-btn vp-prev-btn';
        this.prevBtn.title = '上一幀 (,)';
        this.prevBtn.dataset.order = String(this.options.order);
        this.prevBtn.innerHTML = `<span class="vp-icon-prev">${prevIcon}</span>`;
        this.setupRepeatButton(this.prevBtn, () => this.player.prevFrame?.());
        wrapper.appendChild(this.prevBtn);

        // 下一幀按鈕
        this.nextBtn = document.createElement('button');
        this.nextBtn.className = 'vp-btn vp-next-btn';
        this.nextBtn.title = '下一幀 (.)';
        this.nextBtn.dataset.order = String(this.options.order + 1);
        this.nextBtn.innerHTML = `<span class="vp-icon-next">${nextIcon}</span>`;
        this.setupRepeatButton(this.nextBtn, () => this.player.nextFrame?.());
        wrapper.appendChild(this.nextBtn);

        return wrapper;
    }

    /**
     * 覆寫插入方法，將兩個按鈕分別插入
     */
    protected insertElement(): void {
        const container = this.getControlsContainer();
        if (!container || !this.prevBtn || !this.nextBtn) return;

        this.insertByOrder(container, this.prevBtn);
        this.insertByOrder(container, this.nextBtn);
    }

    /**
     * 設置長按加速重複按鈕
     *
     * 加速機制：
     * - 初始延遲後開始重複
     * - 每次重複後，間隔乘以 accelerationFactor（變快）
     * - 最快不超過 minInterval
     *
     * 例如：初始 100ms，加速因子 0.85，最小 16ms
     * → 100ms → 85ms → 72ms → 61ms → 52ms → 44ms → 37ms → 32ms → 27ms → 23ms → 20ms → 17ms → 16ms
     */
    private setupRepeatButton(button: HTMLElement, action: () => void): void {
        let timeoutId: number | null = null;
        let currentInterval = this.options.repeatInterval;
        let isRepeating = false;

        const stopRepeat = () => {
            if (timeoutId) {
                clearTimeout(timeoutId);
                timeoutId = null;
            }
            isRepeating = false;
            currentInterval = this.options.repeatInterval; // 重置間隔
        };

        const scheduleNext = () => {
            if (!isRepeating) return;

            action();

            // 加速：間隔乘以加速因子，但不低於最小值
            currentInterval = Math.max(
                this.options.minInterval,
                currentInterval * this.options.accelerationFactor
            );

            timeoutId = window.setTimeout(scheduleNext, currentInterval);
        };

        this.on(button, 'mousedown', (e) => {
            e.stopPropagation();
            action(); // 立即執行一次
            isRepeating = true;
            currentInterval = this.options.repeatInterval;

            // 初始延遲後開始加速重複
            timeoutId = window.setTimeout(scheduleNext, this.options.initialDelay);
        });

        this.on(button, 'mouseup', stopRepeat);
        this.on(button, 'mouseleave', stopRepeat);

        // 確保清理定時器
        this.registerCleanup(stopRepeat);
    }

    enable(): void {
        if (this.prevBtn) this.prevBtn.style.display = '';
        if (this.nextBtn) this.nextBtn.style.display = '';
    }

    disable(): void {
        if (this.prevBtn) this.prevBtn.style.display = 'none';
        if (this.nextBtn) this.nextBtn.style.display = 'none';
    }

    destroy(): void {
        // 清理時需要移除兩個按鈕
        this.prevBtn?.remove();
        this.nextBtn?.remove();
        super.destroy();
    }
}
